class AsyncAgent:
    """One of agents: A stored, versioned definition of an agent: its harness (Claude Code, Codex or an image of your own), model, model accounts, instructions, tools and machine. Each start makes a session, a machine of its own that runs the harness, billed as any machine is; model use is billed by the account's provider. An update makes a new version; a session keeps the version it started on."""

    def __init__(self, client: "AsyncAgents", info: AgentInfo) -> None:
        self._c = client
        #: What it was when last read.
        self.info = info

    @property
    def id(self) -> str:
        """Its id."""
        return self.info.id

    @property
    def harness(self) -> Optional[Literal["claude-code", "codex", "custom", "unknown"]]:
        """The harness each session runs: `claude-code`, `codex`, or `custom` (the `start` of `image`); `claude-code` when omitted."""
        return self.info.harness

    @property
    def image(self) -> Optional[str]:
        """The image each session boots, by name (its newest version), `name:version` or ID; the harness's image when omitted. Required for `custom`."""
        return self.info.image

    @property
    def model(self) -> Optional[str]:
        """The model, as its provider names it (`claude-opus-5-5`); the harness's default when omitted."""
        return self.info.model

    @property
    def accounts(self) -> Optional[List[str]]:
        """The model accounts each session may use, by secret name, 1 to 16: an API key or a subscription's token. A session takes the one with the most room left and moves to the next when a provider refuses it for its limit."""
        return self.info.accounts

    @property
    def instructions(self) -> Optional[str]:
        """The instructions each session starts with: its system prompt."""
        return self.info.instructions

    @property
    def tools(self) -> Optional[List["AgentTool"]]:
        """Each tool's policy, by name; a tool none names is allowed."""
        return self.info.tools

    @property
    def mcp_servers(self) -> Optional[List["McpServer"]]:
        """The MCP servers each session connects to."""
        return self.info.mcp_servers

    @property
    def secrets(self) -> Optional[List[str]]:
        """The other secrets each session may get, by name, at most 64: only those of them whose scope admits it; [] none."""
        return self.info.secrets

    @property
    def vcpu(self) -> Optional[int]:
        """Each session's vCPUs."""
        return self.info.vcpu

    @property
    def memory_gb(self) -> Optional[float]:
        """Each session's memory in GB (1 GB is 1,024 MiB); a fraction is taken to the MiB (`1.5`)."""
        return self.info.memory_gb

    @property
    def disk_gb(self) -> Optional[float]:
        """Each session's disk in GB, to the MiB."""
        return self.info.disk_gb

    @property
    def network(self) -> Optional["NetworkRules"]:
        """Where each session may connect out; the open internet behind every machine's walls when omitted."""
        return self.info.network

    @property
    def idle_pause_seconds(self) -> Optional[int]:
        """Seconds with nothing happening before a session pauses, 60 to 86400; 0 never; 300 when omitted. A paused session costs no CPU and wakes when a message is sent to it."""
        return self.info.idle_pause_seconds

    @property
    def max_cost(self) -> Optional[str]:
        """The most one session may cost in machine time, in US dollars (`"1.00"`): a session pauses once it has cost that. Model use is billed by the account's provider."""
        return self.info.max_cost

    @property
    def max_concurrent(self) -> Optional[int]:
        """The most sessions open at once; a start past it is refused 429."""
        return self.info.max_concurrent

    @property
    def object(self) -> Literal["agent", "unknown"]:
        """Always `agent`."""
        return self.info.object

    @property
    def name(self) -> str:
        """Its name, unique in its project."""
        return self.info.name

    @property
    def version(self) -> int:
        """Its version, from 1: each update makes the next. A session keeps the version it was started on."""
        return self.info.version

    @property
    def state(self) -> Literal["active", "deleted", "unknown"]:
        """`active`, or `deleted` in a delete's answer."""
        return self.info.state

    @property
    def labels(self) -> Dict[str, str]:
        """Its labels."""
        return self.info.labels

    @property
    def created_at(self) -> Optional[str]:
        """When it was created."""
        return self.info.created_at

    @property
    def updated_at(self) -> Optional[str]:
        """When its current version was made."""
        return self.info.updated_at

    @property
    def deleted_at(self) -> Optional[str]:
        """When it was deleted: a delete's answer, its state `deleted`."""
        return self.info.deleted_at

    def __repr__(self) -> str:
        return f"AsyncAgent({self.info!r})"

    @classmethod
    async def create(cls, *, api_key: Optional[str] = None, base_url: Optional[str] = None, project: Optional[str] = None, name: str, harness: Optional[Literal["claude-code", "codex", "custom", "unknown"]] = None, image: Optional[str] = None, model: Optional[str] = None, accounts: Optional[List[str]] = None, instructions: Optional[str] = None, tools: Optional[List["AgentTool"]] = None, mcp_servers: Optional[List["McpServer"]] = None, secrets: Optional[List[str]] = None, vcpu: Optional[int] = None, memory_gb: Optional[float] = None, disk_gb: Optional[float] = None, network: Optional["NetworkRules"] = None, idle_pause_seconds: Optional[int] = None, max_cost: Optional[str] = None, max_concurrent: Optional[int] = None, labels: Optional[Dict[str, str]] = None, idempotency_key: Optional[str] = None) -> "AsyncAgent":
        """Makes one and returns it, as ``Runtime().agents.create()`` does, with a client of its own: ``RUNTIME_API_KEY``,
        or ``api_key``. The other arguments are the create's."""
        return await AsyncAgents(AsyncTransport(api_key=api_key, base_url=base_url, project=project)).create(name=name, harness=harness, image=image, model=model, accounts=accounts, instructions=instructions, tools=tools, mcp_servers=mcp_servers, secrets=secrets, vcpu=vcpu, memory_gb=memory_gb, disk_gb=disk_gb, network=network, idle_pause_seconds=idle_pause_seconds, max_cost=max_cost, max_concurrent=max_concurrent, labels=labels, idempotency_key=idempotency_key)

    async def refresh(self, *, wait: Optional[float] = None, if_state: Optional[str] = None) -> "AsyncAgent":
        """Returns an agent at its current version."""
        self.info = (await self._c.get(self.id, wait=wait, if_state=if_state)).info
        return self

    async def update(self, *, harness: Optional[Literal["claude-code", "codex", "custom", "unknown"]] = None, image: Optional[str] = None, model: Optional[str] = None, accounts: Optional[List[str]] = None, instructions: Optional[str] = None, tools: Optional[List["AgentTool"]] = None, mcp_servers: Optional[List["McpServer"]] = None, secrets: Optional[List[str]] = None, vcpu: Optional[int] = None, memory_gb: Optional[float] = None, disk_gb: Optional[float] = None, network: Optional["NetworkRules"] = None, idle_pause_seconds: Optional[int] = None, max_cost: Optional[str] = None, max_concurrent: Optional[int] = None, idempotency_key: Optional[str] = None) -> "AsyncAgent":
        """Changes an agent's settings and makes its next version: each setting named replaces its own, the rest are kept. Sessions started from then on use it; an open session keeps its version."""
        self.info = await self._c.update(self.id, harness=harness, image=image, model=model, accounts=accounts, instructions=instructions, tools=tools, mcp_servers=mcp_servers, secrets=secrets, vcpu=vcpu, memory_gb=memory_gb, disk_gb=disk_gb, network=network, idle_pause_seconds=idle_pause_seconds, max_cost=max_cost, max_concurrent=max_concurrent, idempotency_key=idempotency_key)
        return self

    async def delete(self, *, idempotency_key: Optional[str] = None) -> AgentInfo:
        """Deletes an agent: no session is started from it from then on. Its open sessions run on until they are deleted."""
        return await self._c.delete(self.id, idempotency_key=idempotency_key)

    async def start(self, *, message: Optional[str] = None, key: Optional[str] = None, version: Optional[int] = None, name: Optional[str] = None, labels: Optional[Dict[str, str]] = None, volumes: Optional[List["VolumeMount"]] = None, idempotency_key: Optional[str] = None) -> SandboxInfo:
        """Starts a session: a machine that runs the agent's harness on its model account with the most room left, sent `message` as its first. With the `key` of an open session, sends `message` to that session and returns it. Refused 429 at the agent's maxConcurrent. Asked again with the same Idempotency-Key, it starts nothing more."""
        return await self._c.start(self.id, message=message, key=key, version=version, name=name, labels=labels, volumes=volumes, idempotency_key=idempotency_key)

    async def __aenter__(self) -> "AsyncAgent":
        return self

    async def __aexit__(self, *exc: Any) -> None:
        """Deletes it when the ``async with`` block that holds it ends."""
        await self.delete()


